def is_valid(mosaic, n):
    for i in range(n):
        for j in range(n):
            count = 0
            if i > 0 and mosaic[i-1][j] == mosaic[i][j]:
                count += 1
            if i < n-1 and mosaic[i+1][j] == mosaic[i][j]:
                count += 1
            if j > 0 and mosaic[i][j-1] == mosaic[i][j]:
                count += 1
            if j < n-1 and mosaic[i][j+1] == mosaic[i][j]:
                count += 1
            if count != 2:
                return False
    return True

def fill_mosaic(mosaic, n):
    for i in range(n):
        for j in range(n):
            if mosaic[i][j] == '.':
                # Try filling with S and G and check if it results in a unique or multiple solution
                temp_mosaic_s = [row[:] for row in mosaic]
                temp_mosaic_s[i][j] = 'S'
                temp_mosaic_g = [row[:] for row in mosaic]
