                if is_valid(temp_mosaic_s, n):
                    if is_valid(temp_mosaic_g, n):
                        return 'MULTIPLE'
                    else:
                        mosaic = temp_mosaic_s
                else:
                    if is_valid(temp_mosaic_g, n):
                        mosaic = temp_mosaic_g
                    else:
                        return 'NONE'
    return mosaic

